const SPEECH_AUDIO = 'data:audio/mpeg;base64, '
let speechBuffer = null
export async function prepareBundledSpeech() {
  const ctx = await unlockAudio()
  if (!speechBuffer) {
    const encoded = SPEECH_AUDIO.split(',')[1].trim()
    const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0))
    speechBuffer = await ctx.decodeAudioData(bytes.buffer)
  }
  return ctx
}
function bundledWords(text) {
  return text === 'Left. Right. Ahead. Speech test.' ? [text] : text.split(', ').map(w => SPEECH_SEGMENTS[w] ? w : 'object')
}
function playBundled(text, done) {
  const ctx = getAudioContext()
  if (!speechBuffer || ctx.state !== 'running') throw new Error('Tap Test spoken directions to unlock offline speech.')
  const nodes=[];let at=ctx.currentTime+.03
  for(const word of bundledWords(text)) {
    const [offset,duration]=SPEECH_SEGMENTS[word],node=ctx.createBufferSource()
    node.buffer=speechBuffer;node.connect(ctx.destination);node.start(at,offset,duration)
    nodes.push(node);at+=duration+.08
  }
  nodes.at(-1).onended=done
  return ()=>{for(const node of nodes){node.onended=null;try{node.stop();node.disconnect()}catch{/* Already ended. */}}}
}

// Never select a network voice. A bundled word sprite is independent of the
// Android voice service and is decoded into the already-unlocked audio context.
export function createSpeechController(synth, Utterance, clock = () => performance.now(), fallback = {prepare:prepareBundledSpeech, play:playBundled}) {
  let lastAt=-Infinity,lastKey='',speaking=false,generation=0,stopClip=null,timer=null,testUntil=0,blocked=false,ready=false
  let message='Tap Speech on or Test spoken directions to enable offline words.'
  let listener=()=>{}
  const voices=()=>synth?.getVoices?.()||[]
  const voice=()=>voices().find(v=>v.localService && /^en\b/i.test(v.lang))
  const available=()=>Boolean((synth && Utterance && voice() && !blocked)||ready)
  const inventory=()=>`${voices().length} browser voices; ${voices().filter(v=>v.localService).length} local. ${voice()?`English voice: ${voice().name||voice().lang}.`:'No local English voice.'}`
  const notify=text=>{message=text;listener(`${inventory()} ${text}`)}
  const refresh=()=>listener(`${inventory()} ${message}`)
  synth?.addEventListener?.('voiceschanged',refresh)
  const cancel=()=>{generation++;clearTimeout(timer);synth?.cancel();stopClip?.();stopClip=null;speaking=false}
  const say=(text,key,urgent=false,force=false)=>{
    if(!available())return false
    const now=clock()
    if(!force && (now<testUntil || now-lastAt<(urgent?1800:4000) || (speaking && (!urgent||key===lastKey))))return true
    cancel();const token=generation;lastAt=now;lastKey=key;speaking=true
    const done=()=>{if(token===generation){speaking=false;notify('Speech finished. Physical audibility needs your check.')}}
    const clip=reason=>{
      if(token!==generation)return
      clearTimeout(timer)
      if(!ready){speaking=false;notify(`${reason} Tap Test spoken directions for bundled offline words.`);return}
      try {synth?.cancel();stopClip=fallback.play(text,done);notify(`${reason} Playing bundled offline words.`)}
      catch(err){speaking=false;notify(`Offline speech failed: ${err.message}. Turn Sound on for tones.`)}
    }
    if(ready||!voice()||blocked){clip(blocked?'Browser voice failed.':'');return speaking}
    const u=new Utterance(text);u.voice=voice();u.lang=u.voice.lang;u.rate=1;u.volume=1
    u.onstart=()=>{if(token===generation){clearTimeout(timer);notify(`Browser voice started: ${u.voice.name||u.lang}.`)}}
    u.onend=done
    u.onerror=e=>{if(token===generation){blocked=true;clip(`Browser voice error: ${e.error||'unknown'}.`)}}
    try {synth.resume?.();synth.speak(u);notify('Browser speech requested. Waiting for start.');timer=setTimeout(()=>{if(token===generation){blocked=true;clip('Browser voice did not start.')}},1500);return true}
    catch(err){blocked=true;clip(`Browser voice failed: ${err.message}.`);return speaking}
  }
  return {available,cancel,
    subscribe(fn){listener=fn;refresh();return()=>{listener=()=>{}}},
    dispose(){cancel();synth?.removeEventListener?.('voiceschanged',refresh)},
    cue(selected){if(clock()<testUntil)return true;if(!selected.target){cancel();return available()}const text=speechPhrase(selected);return say(text,`${selected.target.id}:${text}`,selected.kind==='warning')},
    async test(){
      try {await fallback.prepare();ready=true;testUntil=clock()+6000;return say('Left. Right. Ahead. Speech test.','test',false,true)}
      catch(err){notify(`Offline audio unavailable: ${err.message}.`);return say('Left. Right. Ahead. Speech test.','test',false,true)}
    },
  }
   }
